'use strict';
const V2={page:'dashboard',mode:'now',departure:'immediate',at:'2023-09-08T10:00',planned:'',origin:'罗湖',destination:'黄贝岭',vias:[],transport:'公共交通',plans:[],selected:[],focus:null,loading:false,error:'',weather:null,mapTab:'roads',eventTab:'past',eventId:'sep2023',rangeStart:'2023-09-07',rangeEnd:'2023-09-16',query:'',answer:'',settings:stored('sy-v2-settings')||{},shared:null,requestSeq:0};
if(Array.isArray(V2.settings))V2.settings={font:14,voice:false,alert:false,lead:30};
const V2NAV=[['dashboard','出行看板','route'],['map','地点风险','map'],['query','快捷查询','search'],['history','查询记录','clock'],['feedback','用户反馈','message'],['about','关于与设置','layers'],['events','事件追踪与复盘','rain']];
const VC=['#2457e8','#8b63db','#179c8a','#d78538','#c65f8d'];
const tip=(text,detail)=>`<span class="explain" tabindex="0" data-v2="explain" data-detail="${esc(detail)}">${esc(text)}<span class="tooltip" role="tooltip">${esc(detail)}</span></span>`;
const vId=()=>crypto.randomUUID();
function vTime(){return V2.mode==='history'?V2.at:V2.departure==='planned'?V2.planned:null}
function vAvailable(){if(V2.mode==='now')return D.risks.filter(r=>r.guide_year===2026);const t=new Date(V2.at+':00+08:00'),y=[2026,2025,2024,2023].find(y=>new Date((D.guide_dates[y]||`${y}-12-31`)+'T23:59:59+08:00')<=t);return D.risks.filter(r=>r.guide_year===y)}
function vEvents(){return V2.mode==='now'||V2.eventId!=='sep2023'?[]:D.events.filter(e=>new Date(e.available_at)<=new Date(V2.at+':00+08:00'))}
function vResolve(text){const n=text.trim();const match=n.match(/^\s*(\d+(?:\.\d+)?)\s*[,，]\s*(\d+(?:\.\d+)?)\s*$/);if(match){const lat=Number(match[1]),lon=Number(match[2]);if(lat>=22.3&&lat<=22.9&&lon>=113.6&&lon<=114.7)return {name:n,lat,lon,origin:'输入坐标，未核验'};return null}return D.stations.find(s=>[s.name,s.name+'站',s.name+'地铁站'].includes(n))||null}
function vTerms(p){const words=[p?.origin||V2.origin,p?.destination||V2.destination,...(p?.vias||V2.vias),...(p?.roadNames||[])];return [...new Set(words.filter(x=>x&&x.length>=2))]}
function vMatchText(text,terms){return terms.some(t=>text.includes(t)||t.includes(text))}
function vRisks(p){const terms=vTerms(p);return vAvailable().filter(r=>terms.some(t=>r.risk_description.includes(t)||t.includes(r.street.replace('街道',''))||t===r.street))}
function vRelated(p){return vEvents().filter(e=>vMatchText(e.place_text,vTerms(p)))}
function vFeedback(p){const t=V2.mode==='history'?new Date(V2.at+':00+08:00'):new Date();return stored('sy-v2-feedback').filter(f=>f.status!=='已关闭'&&new Date(f.submitted)<=t&&vMatchText(f.place,vTerms(p)))}
function vFocus(){return V2.plans.find(p=>p.id===V2.focus)||V2.plans.find(p=>V2.selected.includes(p.id))||null}
function vContext(){const p=vFocus();return `<div class="context"><span><i class="dot"></i>${V2.mode==='history'?'历史截止 '+esc(dateText(V2.at)):'现在模式 · '+(V2.departure==='planned'?'计划 '+esc(dateText(V2.planned||'未选择')):'立即出发')}</span><span>${esc(p?.origin||V2.origin)} → ${esc(p?.destination||V2.destination)}</span><span>${V2.selected.length} 个方案同时显示</span></div>`}
function vSource(r){return `<button class="linkbutton" data-v2="source" data-kind="risk" data-value="${esc(r.street)}">${r.guide_year}版 · ${D.guide_dates[r.guide_year]||'发布日期待核实'} · 原文 ↗</button>`}
function vEventSource(e){return `<button class="linkbutton" data-v2="source" data-kind="event" data-value="${e.record_id}">发布 ${esc(dateText(e.source_published_at))} · 原文 ↗</button>`}
function vHead(k,t,s,action=''){return pageHeading(k,t,s,action)}
function vForm(){return `<section class="card journey v4journey"><div class="sectiontitle"><span>02</span><div><h2>行程选择</h2><small>按出发点、途经点、目的地填写，查询条件自动保留</small></div></div><form id="v2-journey"><div class="routefields orderedjourney"><div class="field"><label for="v2-origin">出发点</label><input id="v2-origin" name="origin" list="v2-places" value="${esc(V2.origin)}" placeholder="地点，或纬度,经度" required></div><span class="arrow">→</span>${V2.vias.map((v,i)=>`<div class="field viafield"><label>途经点 ${i+1}</label><div class="inlinevia"><input name="via-${i}" data-via="${i}" list="v2-places" value="${esc(v)}" placeholder="选择途经地点"><button type="button" data-v2="remove-via" data-value="${i}" aria-label="删除途经点">×</button></div></div><span class="arrow">→</span>`).join('')}<button type="button" class="addinline" data-v2="add-via" title="在出发点与目的地之间添加途经点">＋途经点</button><div class="field"><label for="v2-destination">目的地</label><input id="v2-destination" name="destination" list="v2-places" value="${esc(V2.destination)}" placeholder="地点，或纬度,经度" required></div></div><datalist id="v2-places">${D.stations.map(s=>`<option value="${s.name}">`).join('')}${D.risks.filter(r=>r.guide_year===2026).map(r=>`<option value="${r.street}">`).join('')}</datalist></form><details class="minidetails"><summary>地点匹配范围</summary><small>地点输入不限于列表。当前自动坐标只覆盖已有站点；其他地点可输入纬度,经度，完整地址搜索仍待接通。</small></details></section>`}
function vWeatherData(){if(V2.mode==='history'){const x=D.weather.find(w=>w.time===V2.at);return {temperature:null,rain:x?.rain,wind:null,time:V2.at,label:'历史天气背景需去事件复盘查看',historical:true}}const w=V2.weather;if(!w)return {label:'天气服务尚未返回'};if(V2.departure==='planned'){const i=w.hourly?.time?.findIndex(t=>t===V2.planned.slice(0,13)+':00')??-1;return {temperature:i>=0?w.hourly.temperature_2m[i]:null,rain:i>=0?w.hourly.precipitation[i]:null,prob:i>=0?w.hourly.precipitation_probability[i]:null,time:i>=0?w.hourly.time[i]:null,label:'Open-Meteo数值预报 · 非官方预警'}}return {temperature:w.current?.temperature_2m,rain:w.current?.precipitation,wind:w.current?.wind_speed_10m,time:w.current?.time,interval:w.current?.interval,label:'Open-Meteo模型天气 · 非本地站点实测'}}
function vWeather(){const w=vWeatherData(),historical=w.historical;return `<section class="card"><div class="row"><h2>天气与预警</h2><span class="tag gray">${V2.mode==='history'?'严格历史模式':'模型天气参考'}</span></div><div class="weathergrid"><div><small>气温</small><b>${!historical&&w.temperature!=null?w.temperature+'°':'—'}</b></div><div><small>${tip('降雨量','雨量是单位面积上收到的水的厚度：10毫米约相当于每平方米10升水。积水深度还受地势、排水和汇水面积影响，不能直接换算。')}</small><b>${!historical&&w.rain!=null?w.rain+' mm':'—'}</b></div><div><small>风速</small><b>${!historical&&w.wind!=null?w.wind+' m/s':'—'}</b></div><div><small>${tip('积水深度','只有对应地点、时间和基准明确的水位或水深观测才显示数值。没有观测时保持未知。')}</small><b>未知</b></div></div><p class="muted">${esc(w.label)}${V2.weather?.place?' · 地点 '+esc(V2.weather.place):''}${w.time&&!historical?' · 数据时刻 '+esc(dateText(w.time)):''}${w.interval?' · 降水统计间隔 '+w.interval+'秒':''}${V2.departure==='planned'?' · 预报1小时累计降水':''}</p><div class="notice">官方预警：原公告未完整接通。${historical?'事后再分析不提前进入历史看板。':'模型天气不会代替官方预警。'}</div><div class="row"><a href="https://weather.sz.gov.cn/" target="_blank" rel="noopener">深圳气象官方发布 ↗</a><button class="linkbutton" data-v2="weather">刷新天气参考</button></div></section>`}
function vPhoto(f){return f.photo?`<button class="phototrigger" data-v2="photo" data-value="${f.id}">现场图片<span class="photohover"><img src="${f.photo}" alt="用户上传现场图片"><small>用户提供 · ${esc(dateText(f.observed))} · 待核验</small></span></button>`:''}
function vHazards(){const p=vFocus(),r=vRisks(p),f=vFeedback(p);return `<section class="card"><h2>相关地点隐患</h2><div class="hazardcolumns"><div><span class="tag">官方资料 · ${r.length}条关联</span>${r.length?r.map(x=>`<div class="listitem"><b>${x.street}</b><p>${esc(x.risk_description)}</p>${vSource(x)}</div>`).join(''):'<div class="empty">没有明确地名匹配。尚未覆盖完整沿线路段，不能据此判断无隐患。</div>'}</div><div><span class="tag orange">用户反馈 · ${f.length}条本地线索</span>${f.length?f.slice(-3).map(x=>`<div class="listitem"><b>${esc(x.place)}</b><p>${esc(x.content)}</p><small>用户自评 ${esc(x.severity)} · ${esc(x.status||'待核验')}</small><br>${vPhoto(x)}</div>`).join(''):'<div class="empty">尚无与行程匹配的本地反馈。多人共享后端未接通。</div>'}</div></div><div class="subtle">自动关联依据为地点词和已取得的路线道路名，不再要求你选择街道；缺少定位的隐患不会伪装成精确路段标记。</div></section>`}
function vPlanCard(p,i){const on=V2.selected.includes(p.id);return `<article class="plancard ${p.id===V2.focus?'focused':''}"><div class="row"><button class="linkbutton" data-v2="focus" data-value="${p.id}" style="color:${VC[i%VC.length]};font-size:14px;font-weight:650">方案${i+1} · ${esc(p.transport)}</button><button class="linkbutton" data-v2="delete-plan" data-value="${p.id}" aria-label="删除方案">删除</button></div><p>${esc(p.origin)} ${p.vias.length?'→ '+p.vias.map(esc).join(' → ')+' ':''}→ ${esc(p.destination)}</p><div class="row"><b>${p.duration!=null?Math.ceil(p.duration/60)+' 分钟':'时长待接入'}</b><small>${p.distance!=null?(p.distance/1000).toFixed(1)+' km':'距离未确认'}</small></div><small>${esc(p.label)}<br>${p.mode==='history'?'历史地点方案':'出发 '+(p.planned?dateText(p.planned):'立即')} · 隐患覆盖不完整</small><div class="row" style="margin-top:12px"><small>${on?'已加入下方比较':'未加入比较'}</small><button class="linkbutton" data-v2="focus" data-value="${p.id}">重新查看 →</button></div></article>`}
function vMap(scope='all'){const selected=scope==='selected'?(vFocus()?[vFocus()]:[]):V2.plans.filter(p=>V2.selected.includes(p.id)),allcoords=[...D.stations.map(s=>[s.lon,s.lat]),...selected.flatMap(p=>p.geometry?.coordinates||p.coords?.map(c=>[c.lon,c.lat])||[])];const minx=Math.min(...allcoords.map(c=>c[0]))-.006,maxx=Math.max(...allcoords.map(c=>c[0]))+.006,miny=Math.min(...allcoords.map(c=>c[1]))-.005,maxy=Math.max(...allcoords.map(c=>c[1]))+.005;const xy=c=>[35+(c[0]-minx)/(maxx-minx)*650,300-(c[1]-miny)/(maxy-miny)*260];return `<section class="card mapcard"><div class="maptop"><div><h2>${scope==='comparison'?'多方案路径与风险对比':scope==='selected'?'当前方案 · 道路与路线位置图':V2.mapTab==='transit'?'公共交通站点':'道路与路线'}</h2><small>站点坐标公开；风险标记区分官方长期隐患、历史停运与用户线索</small></div><span class="tag">${selected.length} 个方案</span></div><div class="mapwrap"><svg viewBox="0 0 720 340" role="img" aria-label="路线和站点位置"><defs><pattern id="v2grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#dce6f3" stroke-width=".7"/></pattern></defs><rect width="720" height="340" fill="#f1f6fc"/><rect width="720" height="340" fill="url(#v2grid)"/>${selected.map(p=>{const coords=p.geometry?.coordinates||p.coords?.map(c=>[c.lon,c.lat])||[],i=V2.plans.indexOf(p);return coords.length>1?`<polyline points="${coords.map(xy).map(c=>c.join(',')).join(' ')}" fill="none" stroke="${vRouteColor(p)}" stroke-width="${p.id===V2.focus?4:2.5}" ${p.geometry?'':'stroke-dasharray="7 6"'} opacity=".8"/>`:''}).join('')}${D.stations.map(s=>{const [x,y]=xy([s.lon,s.lat]),affected=vRelated(vFocus()).some(e=>/暂停/.test(e.category)&&e.place_text.includes(s.name));const official=vAvailable().some(r=>r.risk_description.includes(s.name+'地铁站')),feedback=v3FeedbackSafe().some(f=>f.place.includes(s.name)&&f.status!=='已关闭');return `<g role="button" tabindex="0" data-v2="station" data-value="${s.name}" class="pin"><title>${s.name}：${affected?'当时公告涉及停运':feedback?'用户有报告，待核验':official?'官方长期隐患涉及站点周边':'当前运营状态未知'}；点击查看详情</title><circle cx="${x}" cy="${y}" r="6" fill="white" stroke="${affected?'#ce5360':feedback?'#d38a36':official?'#4c76cb':'#829bc1'}" stroke-width="2.5"/><text x="${x+10}" y="${y+4}" fill="#426082" font-size="11">${s.name}</text></g>`}).join('')}<text x="24" y="325" fill="#889cb8" font-size="10">© OpenStreetMap contributors · ODbL · 坐标未实地核验</text></svg></div><div class="maplegend"><span><i class="key" style="background:#159b8e"></i>已选方案中参考时长较短（不是安全推荐）</span><span>其他颜色：候选路径</span><span>虚线：未规划地点连线</span><span><i class="key gray"></i>状态未知</span><span><i class="key"></i>官方长期隐患</span><span><i class="key orange"></i>用户待核验报告</span><span><i class="key" style="background:#ce5360"></i>历史停运公告涉及</span></div><div class="subtle" style="padding:0 20px 15px">路线服务不包含实时洪涝、封路或拥堵。历史模式只显示地点连线，不把当前路网回算成历史路线。</div></section>`}
function vCompare(){const plans=V2.plans.filter(p=>V2.selected.includes(p.id));return `<section class="card comparesection"><div class="sectiontitle"><span>05</span><div><h2>方案比较</h2><small>选择两条或多条方案，比较路径、交通工具、参考时长和相关事件</small></div></div>${V2.plans.length?`<div class="comparechoices">${V2.plans.map((p,i)=>`<label><input type="checkbox" data-plan="${p.id}" ${V2.selected.includes(p.id)?'checked':''}><i style="background:${vRouteColor(p)}"></i>方案${i+1} · ${esc(p.transport)} · ${esc(p.destination)}</label>`).join('')}</div>`:'<div class="empty">先在上方生成方案，再选择要比较的路线。</div>'}${plans.length>=2?vMap('comparison'):'<div class="empty compactempty">选择至少两个方案后显示路径对比图。</div>'}${plans.length>=2?`<div class="tablewrap comparisondata"><table><thead><tr><th>对比项目</th>${plans.map(p=>`<th><i class="routecolor" style="background:${vRouteColor(p)}"></i>${esc(p.origin)} → ${esc(p.destination)}</th>`).join('')}</tr></thead><tbody>${[['交通工具',p=>p.transport],['参考时长',p=>p.duration!=null?Math.ceil(p.duration/60)+'分钟（非实时）':'未取得'],['路径距离',p=>p.distance!=null?(p.distance/1000).toFixed(1)+'km':'未取得'],['途经点',p=>p.vias.join(' → ')||'未添加'],['官方关联隐患',p=>vRisks(p).map(r=>r.street).join('、')||'未匹配；不代表无隐患'],['相关事件',p=>vRelated(p).map(e=>e.category+' · '+e.place_text).join('；')||'暂无明确匹配记录'],['用户线索',p=>vFeedback(p).length+'条本地记录'],['换乘／费用',()=> '班次与票价待接入']].map(([t,f])=>`<tr><td>${t}</td>${plans.map(p=>`<td>${esc(f(p))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}</section>`}
function vRecommendation(){const p=vFocus(),e=vRelated(p).filter(x=>/暂停|停工|封闭/.test(x.category)),r=vRisks(p);return `<section class="card recommend"><div class="row"><h2>当前方案摘要与注意事项</h2><span class="tag gray">规则整理 · AI待接入</span></div><p>${e.length?'当时公告涉及行程地点；停运及管制区段见下方，非必要行程延后，必要事项优先远程联系目的地。':r.length?'行程地点关联到官方长期隐患，具体地点和来源见下方；此资料不能证明当前道路已经积水。':'沿线资料尚不完整，暂不能比较哪条路线更安全。'}</p><div class="chips"><button data-v2="try-mode" data-value="公共交通">比较公共交通</button><button data-v2="try-mode" data-value="驾车">比较驾车</button><button data-v2="set-planned">查看其他出发时间</button><button data-v2="query-preset" data-value="这趟行程有哪些注意事项？">查看依据</button></div><small>尚未接通真实AI，未自动给出“最安全”“应延后多久”或“不建议出门”的模型结论；官方明确要求会按原文呈现。</small></section>`}
function vDashboard(){return vHead('WEATHER → JOURNEY → OPTIONS','天气与出行安排','按一趟行程的顺序查看，选方案、看路径，再比较。',`<div class="chips"><button data-v2="share">分享查询</button><button data-v2="export">选择导出内容</button></div>`)+`<section class="weatherfirst"><div class="weatherinner"><div class="sectiontitle"><span>01</span><div><h2>天气与出发时间</h2><small>模型天气与官方预警分开呈现</small></div></div>${vWeather()}</div>${vTimeControls()}</section>`+vForm()+`<section class="card planssection"><div class="sectiontitle"><span>03</span><div><h2>出行方案</h2><small>点击方案查看单条路径，勾选后在下方进行比较</small></div></div><div class="plancontrols"><div class="chips">${['公共交通','步行','驾车'].map(t=>`<button data-v2="transport" data-value="${t}" class="${V2.transport===t?'active':''}">${icon(t==='公共交通'?'route':t==='步行'?'map':'route',15)} ${t}</button>`).join('')}</div><button form="v2-journey" type="submit" class="primary" ${V2.loading?'disabled':''}>${V2.loading?'正在查询…':'生成／添加方案'}</button></div>${V2.error?`<div class="notice warn">${esc(V2.error)}</div>`:''}<div class="plancardsgrid">${V2.plans.length?V2.plans.map(vPlanCard).join(''):'<div class="empty" style="grid-column:1/-1">填写行程后选择交通工具，生成方案。驾车可尝试公开路线服务；公共交通和步行待接入完整规划。</div>'}</div>${vContext()}${vMap('selected')}<div class="planadviceinline">${vRecommendation()}</div></section><section class="hazardssection"><div class="sectiontitle"><span>04</span><div><h2>当前方案关联隐患</h2><small>聚焦所查看的路径，官方资料与用户线索分别保留</small></div></div>${vHazards()}${vRelated(vFocus()).length?`<details class="card eventdetails"><summary>相关公告与事件 · ${vRelated(vFocus()).length}条</summary>${vRelated(vFocus()).map(e=>`<div class="listitem"><b>${esc(e.place_text)}</b><p data-original>${esc(e.summary)}</p>${vEventSource(e)}</div>`).join('')}</details>`:''}</section>${vCompare()}`}

function vMapPage(){return vHead('PLACE & STATUS','地点风险','道路与公共交通分别查看。隐患颜色表示来源状态，不伪装成危险概率。')+vContext()+`<div class="seg"><button data-v2="map-tab" data-value="roads" class="${V2.mapTab==='roads'?'active':''}">道路</button><button data-v2="map-tab" data-value="transit" class="${V2.mapTab==='transit'?'active':''}">公共交通</button></div><div style="margin-top:18px">${vMap()}</div><div class="uppergrid">${vHazards()}<section class="card"><h2>周边设施与状态</h2><p>可聚焦公开站点，查看坐标与公告。商场地点、营业状态、入口关闭和实时拥挤数据尚未接入。</p><div class="notice">不把营业时间当作实时开门状态，不依据无报告推断设施可用。</div><p>${tip('状态未知','没有足够的新公告或核验数据时保持未知。用户报告与官方状态独立显示。')}</p></section></div>`}
function vQueryPage(){const q=['这趟行程有哪些注意事项？','哪些停运公告与行程有关？','降雨量和积水深度怎么理解？','当前还缺什么信息？'];return vHead('QUICK ANSWERS','快捷查询','自动使用当前关注方案和查询时间。')+vContext()+`<section class="card"><div class="questiongrid">${q.map(x=>`<button data-v2="query-preset" data-value="${x}">${x} ↗</button>`).join('')}</div><form id="v2-query" class="queryform"><input name="question" value="${esc(V2.query)}" placeholder="查询隐患、公告、雨量解释或数据状态" required><button class="primary">查询资料</button></form>${V2.answer?`<div class="answer">${V2.answer}</div>`:'<div class="empty">资料检索可用，生成式AI尚未接通。</div>'}</section>`}
function vAnswer(q){const p=vFocus(),r=vRisks(p),e=vRelated(p);let html;if(/雨量|积水深度/.test(q))html='<p>雨量表示降水厚度，10mm约等于每平方米10升水。积水深度还受地势、排水和汇水影响，不能直接由下雨时长换算。本站没有可用的实时积水深度。</p>';else if(/停运|公告/.test(q))html=e.length?e.map(x=>`<p>${esc(x.place_text)}：${esc(x.summary)}</p>${vEventSource(x)}`).join(''):'<p>没有匹配的已发布交通记录，当前通行状态未确认。</p>';else if(/隐患|注意事项/.test(q))html=r.length?r.map(x=>`<p>${esc(x.street)}：${esc(x.risk_description)}</p>${vSource(x)}`).join(''):'<p>地名匹配未发现明确关联，沿线风险定位不完整。不能判断无风险。</p>';else if(/缺|数据|状态/.test(q))html='<p>当前缺少官方动态预警、站点短时雨量、水位、公交班次、完整沿线隐患定位、共享用户反馈和AI服务。</p>';else html='<p>这个问题暂未匹配到明确资料。请选择上方查询类别；不会用通用街道回答冒充对问题的理解。</p>';return `<h3>${esc(q)}</h3><span class="tag gray">资料检索 · 非AI生成</span>${html}`}
function vHistoryPage(){const h=stored('sy-v2-history');return vHead('YOUR SEARCHES','查询记录','保存当时结果，支持重新查看、比较、删除、分享和按需导出。')+`<section class="card">${h.length?h.slice().reverse().map(x=>`<article class="historyitem"><div><b>${esc(x.origin)} → ${esc(x.destination)}</b><p>${esc(x.transport)} · ${x.mode==='history'?'历史 '+dateText(x.at):x.planned?'计划 '+dateText(x.planned):'立即出发'}</p><small>查询 ${esc(dateText(x.created))} · ${x.label}</small></div><div class="chips"><button data-v2="restore" data-value="${x.id}">重新查看</button><button data-v2="add-compare" data-value="${x.id}">加入比较</button><button data-v2="share-record" data-value="${x.id}">分享</button><button data-v2="export-record" data-value="${x.id}">选择导出</button><button data-v2="delete-record" data-value="${x.id}">删除</button></div></article>`).join(''):'<div class="empty">完成一次查询后，记录将保存在本浏览器。</div>'}<div class="subtle">重新查看恢复该查询的模式和时间；加入比较不会覆盖其他方案。旧记录不会被重新查询结果悄悄改写。</div></section>`}
function vFeedbackPage(){const f=stored('sy-v2-feedback');return vHead('OBSERVATIONS & PROGRESS','用户反馈','现场事实、严重程度自评与核验进度分别记录。',`<button data-v2="feedback-export">导出上报摘要</button>`)+`<div class="notice">本版反馈仅保存在本浏览器。加急表示优先核验标记，未自动提交官方。</div><div class="panelgrid"><section class="card"><h2>提交反馈</h2><form id="v2-feedback" class="feedbackform"><div class="field"><label>反馈类型</label><select name="type"><option>现场情况</option><option>信息错误</option><option>使用感受</option></select></div><div class="field"><label>地点</label><input name="place" value="${esc(V2.destination)}" required></div><div class="field"><label>观察时间</label><input type="datetime-local" name="observed" required></div><div class="field"><label>用户自评严重程度</label><select name="severity"><option>一般影响</option><option>明显影响</option><option>疑似紧急危险</option></select></div><div class="field"><label>来源</label><select name="basis"><option>本人观察</option><option>转述，尚未核实</option></select></div><div class="field"><label>现场图片 · 可选（JPEG/PNG/WebP）</label><input type="file" name="photo" accept="image/jpeg,image/png,image/webp"><small>图片只存本地，请避免包含可识别个人信息。</small></div><div class="field full"><label>情况描述</label><textarea name="content" required placeholder="描述实际看到的情况，未知水深不猜测"></textarea></div><div class="full"><button class="primary">提交本地反馈</button></div></form></section><section class="card"><h2>我的反馈与处理进度</h2>${f.length?f.slice().reverse().map(x=>`<div class="listitem"><div class="row"><b>${esc(x.place)}</b><span class="tag ${x.severity==='疑似紧急危险'?'red':'orange'}">${esc(x.severity)}</span></div><p>${esc(x.content)}</p><small>观察 ${esc(dateText(x.observed))} · ${esc(x.basis)}</small><br>${vPhoto(x)}${typeof v3FeedbackProgress==='function'?v3FeedbackProgress(x):'<div class="feedbackprogress">已保存在本地 → 待核验</div>'}${x.severity==='疑似紧急危险'?'<div class="notice warn">加急核验标记 · 尚无官方上报回执</div>':''}<button class="linkbutton" data-v2="delete-feedback" data-value="${x.id}">删除本地反馈</button></div>`).join(''):'<div class="empty">尚无反馈，不预填模拟用户人数或处理进度。</div>'}</section></div>`}
function vAbout(){return vHead('ABOUT & PREFERENCES','关于与设置','面向罗湖区出行居民的气候适应实践。项目说明与使用偏好集中在这里。')+`<div class="panelgrid"><section class="card"><h2>深雨知路</h2><p>将公开官方资料整理为与行程有关的隐患、交通信息和可追溯建议，支持历史复盘与现场线索记录。</p><div class="listitem"><b>项目与维护</b><p>个人参赛项目；姓名、联系方式和维护承诺尚未填写，不预填虚构团队信息。</p></div><div class="listitem"><b>AI具体任务</b><p>计划接入公告提取、语义匹配、带依据的解释与反馈整理。当前仍为规则检索，模型尚未连接。</p></div><div class="listitem"><b>数据与验证</b><p>四版罗湖官方指引、18条历史事实、11个公开站点；沿线隐患定位不完整。真实用户试验与预测验证尚未开展。</p><a href="https://weather.sz.gov.cn/" target="_blank" rel="noopener">深圳气象</a> · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OSM许可</a> · <a href="https://project-osrm.org/docs/v5.24.0/api/" target="_blank" rel="noopener">OSRM路线说明</a></div><div class="notice">日期精度和事后资料继续保守处理。公开驾车路线不是洪涝安全导航。</div><a href="source.zip" download>下载代码与续做说明 ↗</a></section><section class="card"><h2>阅读与提醒偏好</h2><div class="field" style="margin-top:20px"><label for="v2-font">字体大小</label><select id="v2-font">${[14,16,18].map(n=>`<option value="${n}" ${Number(V2.settings.font)===n?'selected':''}>${n===14?'标准':n===16?'较大':'大字'}</option>`).join('')}</select></div><div class="settingrow"><label><input id="v2-voice" type="checkbox" ${V2.settings.voice?'checked':''}> 启用语音播报</label><button data-v2="speak">试播当前概要</button></div><div class="settingrow"><label><input id="v2-alert" type="checkbox" ${V2.settings.alert?'checked':''}> 保存提前提醒偏好</label></div><div class="field"><label>提前多久</label><select id="v2-lead">${[15,30,60].map(n=>`<option value="${n}" ${Number(V2.settings.lead)===n?'selected':''}>${n}分钟</option>`).join('')}</select></div><p class="muted">语音使用浏览器支持能力。提前提醒仅保存偏好，后台检查和推送未接通，不能保证收到提醒。</p></section></div>`}
function vEventsPage(){const sep=V2.eventId==='sep2023',all=sep?D.events.filter(e=>{const date=(e.event_start||'2023-09-08').slice(0,10);return date>=V2.rangeStart&&date<=V2.rangeEnd}):[];return vHead('EVENT TRACKING & REVIEW','事件追踪与复盘','完整复盘与专业预测追踪分开；用户报告留在反馈面板。')+`<div class="seg"><button data-v2="event-tab" data-value="past" class="${V2.eventTab==='past'?'active':''}">过去事件</button><button data-v2="event-tab" data-value="now" class="${V2.eventTab==='now'?'active':''}">正在发生</button></div>${V2.eventTab==='past'?`<section class="card" style="margin-top:18px"><div class="historyctrl"><label>事件</label><select id="v2-recap-event"><option value="sep2023" ${sep?'selected':''}>2023年9月深圳暴雨</option><option value="saola2023" ${!sep?'selected':''}>2023年苏拉（资料待补）</option></select><label>范围</label><input id="v2-range-start" type="date" value="${V2.rangeStart}"> — <input id="v2-range-end" type="date" value="${V2.rangeEnd}"></div><div class="notice">完整复盘可包含事后资料，点击“查看当时”回到严格发布时间过滤。没有明确事件时间的记录按案例日期暂放，时间精度仍在详情中保留。</div>${all.length?all.map(e=>`<article class="event"><div class="row"><b>${esc(e.category)} · ${esc(e.place_text)}</b><span class="tag gray">${e.source_published_at.startsWith('2023-09-11')||e.source_published_at.startsWith('2023-09-15')?'事后记录':'历史事实'}</span></div><p data-original>${esc(e.summary)}</p><small>事件 ${esc(e.event_time_text)}</small>${vEventSource(e)}${e.event_start?.includes('T')?` <button class="linkbutton" data-v2="replay" data-value="${e.event_start.slice(0,16)}">查看当时 →</button>`:''}</article>`).join(''):'<div class="empty">此事件／时间范围尚无完整记录。未用其他事件填充。</div>'}</section>`:`<section class="card" style="margin-top:18px"><h2>当前专业事件信息</h2><div class="notice">目前未取得已确认正在发生的专业事件数据。以下记录区不使用用户报告作为预测验证真值。</div><div class="progresscards"><div class="empty">相关机构预测<br>待接入（机构、发布时间、适用范围）</div><div class="empty">AI摘要<br>模型未连接</div><div class="empty">专业观测与核验结果<br>待取得</div><div class="empty">专家差异解释<br>专业解释须注明人员姓名、发布时间和判断依据</div></div><div class="chips" style="margin-top:18px"><a href="https://weather.sz.gov.cn/" target="_blank" rel="noopener">查看气象机构最新发布 ↗</a><a href="https://swj.sz.gov.cn/" target="_blank" rel="noopener">水务局 ↗</a></div></section>`}`}
function vRender(){const pages={dashboard:vDashboard,map:vMapPage,query:vQueryPage,history:vHistoryPage,feedback:vFeedbackPage,about:vAbout,events:vEventsPage,help:()=>typeof vHelpPage==='function'?vHelpPage():'帮助页面正在加载'},title=V2NAV.find(n=>n[0]===V2.page)?.[1];document.documentElement.style.setProperty('--user-font',(V2.settings.font||14)+'px');$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">${icon('rain',26)}</div><div><b>深雨知路</b><small>RAINWISE · LUOHU</small></div></div><nav class="nav" aria-label="主导航">${V2NAV.map(([id,t,i])=>`<button data-v2="page" data-value="${id}" class="${V2.page===id?'active':''}" ${V2.page===id?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('')}</nav><div class="sidefoot"><div class="line"></div><b>你的行程，多一份依据</b>深圳罗湖区 · 出行信息Demo<br>官方资料与用户线索分开呈现<br><br>真实AI与共享反馈待接入</div></aside><main class="main"><header class="topbar"><div class="breadcrumb">深圳 / 罗湖区 <span style="padding:0 12px">/</span><b>${title}</b></div><span class="topbadge">${['help','about'].includes(V2.page)?'账户与软件服务':(V2.mode==='history'?'历史模式':'现在模式')+' · '+V2.plans.length+'个方案'}</span></header><div class="content">${V2.shared?'<div class="notice">正在查看分享快照，不代表当前实时状态。只有公开依据和查询摘要；不包含个人反馈图片。</div>':''}${pages[V2.page]()}<footer class="footer"><span>深雨知路 · 与地点、时间和行程有关的信息</span><span>事实有出处 · 未知不冒充安全</span></footer></div></main></div>`}
function vDraft(){const a=document.getElementById('v2-origin'),b=document.getElementById('v2-destination');if(a)V2.origin=a.value;if(b)V2.destination=b.value;document.querySelectorAll('[data-via]').forEach(x=>V2.vias[Number(x.dataset.via)]=x.value);const p=document.getElementById('v2-planned');if(p)V2.planned=p.value}
async function vFetchWeather(){if(V2.mode==='history')return;const queryDestination=V2.destination;const s=vResolve(V2.destination)||vResolve(V2.origin);if(!s)return;try{const url=`https://api.open-meteo.com/v1/forecast?latitude=${s.lat}&longitude=${s.lon}&current=temperature_2m,precipitation,wind_speed_10m&hourly=temperature_2m,precipitation,precipitation_probability&timezone=Asia%2FShanghai&wind_speed_unit=ms`;const res=await fetch(url,{signal:AbortSignal.timeout(15000)});if(!res.ok)throw Error('服务未返回');const w=await res.json();if(!w.current||!w.hourly)throw Error('数据结构不完整');if(V2.mode==='history'||V2.destination!==queryDestination)return;V2.weather=w;V2.weather.place=s.name;vDraft();vRender();}catch{V2.weather=null;toast('天气服务暂不可用，保持未知');}}
async function vAddPlan(){vDraft();if(!V2.origin.trim()||!V2.destination.trim())return toast('请填写出发点和目的地');if(V2.mode==='now'&&V2.departure==='planned'&&!V2.planned)return toast('请选择计划出发时间');if(V2.planned&&V2.mode==='now'&&V2.departure==='planned'&&new Date(V2.planned+':00+08:00')<businessNow())return toast('计划出发时间不能早于现在');const requestSeq=++V2.requestSeq;V2.shared=null;V2.loading=true;V2.weather=null;V2.error='';vRender();const plan={id:vId(),origin:V2.origin.trim(),destination:V2.destination.trim(),vias:V2.vias.map(x=>x.trim()).filter(Boolean),transport:V2.transport,eventId:V2.eventId,mode:V2.mode,at:V2.at,planned:V2.departure==='planned'?V2.planned:'',created:businessNow().toISOString(),actual_created_at:new Date().toISOString(),label:'地点方案 · 路线待规划',duration:null,distance:null,geometry:null,roadNames:[]};const names=[plan.origin,...plan.vias,plan.destination],coords=names.map(vResolve);plan.coords=coords.filter(Boolean);if(coords.some(x=>!x))V2.error='部分地点尚未匹配坐标。已保存文字地点方案；如需路线，可输入“纬度,经度”。';else if(plan.transport==='驾车'&&plan.mode==='now'){try{const url=`https://router.project-osrm.org/route/v1/driving/${coords.map(x=>x.lon+','+x.lat).join(';')}?alternatives=3&overview=full&geometries=geojson&steps=true`;const resp=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!resp.ok)throw Error('路线服务不可用');const out=await resp.json();if(out.code!=='Ok'||!out.routes?.length)throw Error('没有取得路线');if(requestSeq!==V2.requestSeq)return;out.routes.slice(0,3).forEach((r,i)=>{const p={...plan,id:vId(),geometry:r.geometry,duration:r.duration,distance:r.distance,label:'OSRM驾车参考 · 不含实时路况',roadNames:[...new Set((r.legs||[]).flatMap(l=>(l.steps||[]).map(s=>s.name).filter(Boolean)))]};vCommitPlan(p)});V2.loading=false;vRender();vFetchWeather();return;}catch(e){if(requestSeq!==V2.requestSeq)return;V2.error='路线服务未返回可用结果；已保存地点方案，不使用虚构路线和时长。'}}else if(plan.mode==='history')plan.label='历史地点方案 · 未取得当时路网';else plan.label=plan.transport+'地点方案 · 班次／步行路由待接入';if(requestSeq!==V2.requestSeq)return;vCommitPlan(plan);V2.loading=false;vRender();vFetchWeather();}
function vCommitPlan(p){V2.plans.push(p);V2.selected.push(p.id);V2.focus=p.id;const h=stored('sy-v2-history');h.push({...p,riskRefs:vRisks(p).map(r=>({street:r.street,year:r.guide_year})),eventRefs:vRelated(p).map(e=>e.record_id)});save('sy-v2-history',h.slice(-50));}
function vRestore(p,compare=false){if(!p)return;if(!compare){V2.mode=p.mode;V2.eventId=p.eventId||'sep2023';V2.at=p.at;V2.origin=p.origin;V2.destination=p.destination;V2.vias=p.vias||[];V2.transport=p.transport;V2.departure=p.planned?'planned':'immediate';V2.planned=p.planned||'';V2.plans=[p];V2.selected=[p.id];V2.focus=p.id;V2.page='dashboard';V2.answer='';V2.weather=null;}else {if(p.mode!==V2.mode||(p.mode==='history'&&p.at!==V2.at)){toast('不同资料模式或历史截止时刻不能直接混合比较，请先重新查看该记录');return}if(!V2.plans.some(x=>x.id===p.id))V2.plans.push(p);if(!V2.selected.includes(p.id))V2.selected.push(p.id);V2.focus=p.id;V2.page='dashboard';}vRender();}
function vDialog(title,body){$('#source-dialog').innerHTML=`<button class="close" data-v2="close-dialog" aria-label="关闭">×</button><h2>${esc(title)}</h2>${body}`;if(!$('#source-dialog').open)$('#source-dialog').showModal();}
function vSourceDialog(kind,val){if(kind==='risk'){const r=vAvailable().find(r=>r.street===val);if(!r)return;vDialog(r.street+' · '+r.guide_year+'版官方资料',`<div class="sourceoriginal">${esc(r.risk_description)}</div><p>${esc(r.threshold_original)}</p><p>发布时间：${D.guide_dates[r.guide_year]||'未核实，历史按年末保守启用'}<br>定位：${esc(r.source_location)}</p><a href="${esc(r.source_url)}" target="_blank" rel="noopener">官方原始附件 ↗</a><p>静态隐患不是当前积水证明，未取得现场水深。</p>`);}else{const e=D.events.find(e=>e.record_id===val);if(!e)return;vDialog(e.category+' · '+e.place_text,`<div class="sourceoriginal">${esc(e.summary)}</div><p>事件时间：${esc(e.event_time_text)}<br>资料发布：${esc(dateText(e.source_published_at))}<br>时间精度：${esc(e.source_published_precision)}</p><p>${esc(e.caveat)}</p><a href="${esc(e.source_url)}" target="_blank" rel="noopener">官方原文 ↗</a>`);}}
function vPhotoDialog(id){const f=stored('sy-v2-feedback').find(x=>x.id===id);if(f?.photo)vDialog('现场图片 · 用户提供',`<img src="${f.photo}" alt="用户提供现场图片" style="width:100%;border-radius:10px"><p>${esc(f.place)} · 观察 ${esc(dateText(f.observed))}</p><p>用户自评 ${esc(f.severity)}；状态待核验。上传前请处理个人信息。</p>`);}
function vRecord(id){return stored('sy-v2-history').find(x=>x.id===id)}
const EXPORT_FIELDS=[['journey','行程与出发时间'],['plans','选择的方案与对比'],['weather','天气与预警'],['official','官方隐患与出处'],['feedback','用户反馈（默认不含）'],['advice','建议与适用范围'],['map','路线位置图'],['photos','现场图片（仅图片／HTML导出）']];
let vExportRecord=null;
function vExportDialog(p=null){vExportRecord=p;vDialog('选择导出内容',`<form id="v2-export"><div class="exportchoices">${EXPORT_FIELDS.map(([id,t])=>`<label><input type="checkbox" name="${id}" ${!['feedback','photos'].includes(id)?'checked':''}> ${t}</label>`).join('')}</div><div class="field" style="margin-top:18px"><label>格式</label><select name="format"><option value="html">HTML信息卡（可打印）</option><option value="txt">纯文本</option><option value="png">PNG图片信息卡</option></select></div><div class="notice">来源、发布时间、核验状态和适用范围随相关内容保留。用户内容由你核对后选择；纯文本不包含图片。</div><button class="primary">预览与导出</button></form>`);}
function vSnapshot(p){const plans=p?[p]:V2.plans.filter(x=>V2.selected.includes(x.id));const focus=p||vFocus();return {created:new Date().toISOString(),mode:p?.mode||V2.mode,at:p?.at||V2.at,origin:p?.origin||V2.origin,destination:p?.destination||V2.destination,vias:p?.vias||V2.vias,transport:p?.transport||V2.transport,planned:p?.planned||(V2.departure==='planned'?V2.planned:''),plans,riskRefs:focus?.riskRefs||vRisks(focus).map(r=>({street:r.street,year:r.guide_year})),eventRefs:focus?.eventRefs||vRelated(focus).map(e=>e.record_id),weather:V2.weather?{current:V2.weather.current,place:V2.weather.place}:null};}
function vExportParts(snapshot,chosen){const p=snapshot.plans[0],refs=snapshot.riskRefs.map(x=>D.risks.find(r=>r.street===x.street&&r.guide_year===x.year)).filter(Boolean),ev=snapshot.eventRefs.map(id=>D.events.find(e=>e.record_id===id)).filter(Boolean);const parts=[];if(chosen.journey)parts.push({title:'行程与时间',text:`${snapshot.origin} → ${snapshot.vias.length?snapshot.vias.join(' → ')+' → ':''}${snapshot.destination}\n${snapshot.transport}；${snapshot.mode==='history'?'历史截止 '+dateText(snapshot.at):snapshot.planned?'计划 '+dateText(snapshot.planned):'立即出发'}\n查询快照 ${dateText(snapshot.created)}`});if(chosen.plans)parts.push({title:'方案对比',text:snapshot.plans.map((x,i)=>`方案${i+1} ${x.transport}：${x.origin} → ${x.destination}；${x.duration!=null?Math.ceil(x.duration/60)+'分钟（非实时）':'时长未取得'}；${x.label}`).join('\n')||'未选择方案'});if(chosen.weather)parts.push({title:'天气与预警',text:snapshot.mode==='history'?'历史看板没有可用的当时天气观测；事后ERA5只用于复盘。':snapshot.weather?`Open-Meteo模型天气（非站点实测）\n地点${snapshot.weather.place}；数据时刻${snapshot.weather.current.time}；气温${snapshot.weather.current.temperature_2m}°C\n模型天气时段见数据表；此地点的实时官方预警与水深未接入。`:'未取得天气数据；此地点的动态官方预警与水深未接入。'});if(chosen.official)parts.push({title:'官方隐患与公告',text:refs.map(r=>`${r.street}（${r.guide_year}版）：${r.risk_description}\n发布 ${D.guide_dates[r.guide_year]||'未核实'}\n来源 ${r.source_url}`).concat(ev.map(e=>`${e.place_text}：${e.summary}\n发布 ${dateText(e.source_published_at)}\n来源 ${e.source_url}`)).join('\n\n')||'没有明确匹配记录，沿线隐患覆盖不完整。'});if(chosen.feedback){const f=stored('sy-v2-feedback').filter(f=>vMatchText(f.place,vTerms(p)));parts.push({title:'用户反馈（待核验）',text:f.map(f=>`${f.place}：${f.content}\n观察${dateText(f.observed)}；自评${f.severity}；${f.basis}；待核验`).join('\n\n')||'没有匹配本地反馈'});}if(chosen.advice)parts.push({title:'建议与适用范围',text:'本报告列出已关联公告的发布时间、适用地点和区段。长期隐患不等于实际积水，用户报告不等于官方确认。路线估算未考虑实时洪涝、拥堵及封闭。参考路线不包含实时积水、封路或拥堵，不能据此确认可通行。'});return parts;}
function vExportHtml(parts,snapshot,chosen){return `<!doctype html><meta charset="utf-8"><title>深雨知路信息卡</title><style>body{font:16px/1.8 sans-serif;max-width:850px;margin:30px auto;padding:25px;color:#102344}section{padding:15px;border-bottom:1px solid #ddd}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}img{max-width:100%}</style><h1>深雨知路 · 查询信息卡</h1>${parts.map(p=>`<section><h2>${esc(p.title)}</h2><pre>${esc(p.text)}</pre></section>`).join('')}${chosen.map?'<section><h2>地图范围说明</h2><p>下图位置与路线为查看时快照，当前通行状态未知。实线为参考驾车路线，虚线为地点连线。</p>'+vMapSvgSnapshot(snapshot)+'</section>':''}${chosen.photos?stored('sy-v2-feedback').filter(f=>f.photo&&vMatchText(f.place,vTerms(snapshot.plans[0]))).map(f=>`<section><h2>现场图片 · 待核验</h2><img src="${f.photo}" alt="用户图片"><p>${esc(f.place)}；观察${esc(dateText(f.observed))}；用户提供，未经专业核验</p></section>`).join(''):''}<small>保留发布时间和来源，不使用这张卡保证安全通行。</small>`;}
function vMapSvgSnapshot(s){const pts=s.plans.flatMap(p=>p.geometry?.coordinates||p.coords?.map(x=>[x.lon,x.lat])||[]);if(!pts.length)return '<p>没有可绘制的位置数据。</p>';const xs=pts.map(x=>x[0]),ys=pts.map(x=>x[1]),minx=Math.min(...xs),miny=Math.min(...ys),dx=Math.max(...xs)-minx||.01,dy=Math.max(...ys)-miny||.01;return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 700 280"><rect width="700" height="280" fill="#f2f6fc"/>${s.plans.map((p,i)=>{const c=p.geometry?.coordinates||p.coords?.map(x=>[x.lon,x.lat])||[];return `<polyline points="${c.map(x=>(35+(x[0]-minx)/dx*630)+','+(240-(x[1]-miny)/dy*200)).join(' ')}" stroke="${VC[i%VC.length]}" stroke-width="4" fill="none" ${p.geometry?'':'stroke-dasharray="8 6"'}/>`}).join('')}<text x="20" y="265" font-size="12" fill="#64748b">参考路线／地点连线 · 非安全导航</text></svg>`;}
async function vPng(parts,snapshot,chosen){const lines=[];for(const p of parts){lines.push({text:p.title,title:true});for(const row of p.text.split('\n')){for(let i=0;i<row.length;i+=42)lines.push({text:row.slice(i,i+42)})}lines.push({text:''});}const canvas=document.createElement('canvas');canvas.width=1000;const pics=chosen.photos?stored('sy-v2-feedback').filter(f=>f.photo&&vMatchText(f.place,vTerms(snapshot.plans[0]))):[];canvas.height=Math.max(450,160+lines.length*32+(chosen.map?480:0)+pics.length*400);const c=canvas.getContext('2d');c.fillStyle='#f5f8fd';c.fillRect(0,0,canvas.width,canvas.height);c.fillStyle='#102344';c.font='bold 32px sans-serif';c.fillText('深雨知路 · 查询信息卡',50,65);let y=125;for(const l of lines){c.font=l.title?'bold 21px sans-serif':'18px sans-serif';c.fillStyle=l.title?'#2457e8':'#334155';c.fillText(l.text,50,y);y+=32;}if(chosen.map){const svg=vMapSvgSnapshot(snapshot);if(svg.startsWith('<svg')){const im=new Image();await new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=reject;im.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)});c.drawImage(im,50,y,900,460);y+=480;}}for(const f of pics){const im=new Image();await new Promise((res,rej)=>{im.onload=res;im.onerror=rej;im.src=f.photo});c.fillStyle='#64748b';c.font='18px sans-serif';c.fillText(`${f.place} · 用户图片待核验 · ${dateText(f.observed)}`,50,y);y+=30;const scale=Math.min(900/im.width,330/im.height);c.drawImage(im,50,y,im.width*scale,im.height*scale);y+=370;}const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw Error('图片导出失败');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='深雨知路_信息卡.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let vShareUrl='';let vShareRecord=null;
function vShare(p){vShareRecord=p||null;const s=vSnapshot(p);s.plans=s.plans.map(p=>({...p,geometry:p.geometry?{type:'LineString',coordinates:p.geometry.coordinates.filter((c,i,a)=>i===0||i===a.length-1||i%Math.max(1,Math.floor(a.length/60))===0)}:null,roadNames:p.roadNames?.slice(0,20)}));const payload={version:2,snapshot:s};const code=btoa(unescape(encodeURIComponent(JSON.stringify(payload))));vShareUrl=location.origin+location.pathname+'#snapshot='+code;if(vShareUrl.length>30000){toast('快照过大，请减少方案，或导出图片分享');return;}vDialog('分享这次查询',`<p>链接包含当前查询快照与公开依据引用，不包含个人反馈、图片或身份信息。</p><div class="notice">本站目前为私有版本；接收者需要本站访问权限。链接分享不会自动开放网站。</div><div class="chips"><button class="primary" data-v2="copy-share">复制快照链接</button><button data-v2="native-share">系统分享</button><button data-v2="share-image">生成图片信息卡</button></div><p><small>分享时刻 ${esc(dateText(s.created))}；接收者看到的是历史快照，不代表当前实时状态。</small></p>`);}
async function vReadPhoto(file){if(!file||!file.size)return null;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('请上传8MB以内的JPEG、PNG或WebP');const data=await new Promise((r,j)=>{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.onerror=j;fr.readAsDataURL(file)});const im=new Image();await new Promise((r,j)=>{im.onload=r;im.onerror=j;im.src=data});const scale=Math.min(1,1200/Math.max(im.width,im.height)),canvas=document.createElement('canvas');canvas.width=Math.round(im.width*scale);canvas.height=Math.round(im.height*scale);canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.72);}
function vSpeak(){if(!('speechSynthesis' in window))return toast('此浏览器未提供语音播报');const p=vFocus(),text=`当前关注行程：${p?.origin||V2.origin}到${p?.destination||V2.destination}。官方隐患关联${vRisks(p).length}条，覆盖不完整。当前通行状态需查看最新公告。`;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';window.speechSynthesis.speak(u);}
document.addEventListener('input',e=>{if(vFormId(e.target)==='v2-origin')V2.origin=e.target.value;if(vFormId(e.target)==='v2-destination')V2.destination=e.target.value;if(e.target.dataset?.via!=null)V2.vias[Number(e.target.dataset.via)]=e.target.value;});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-v2]');if(!b)return;const a=b.dataset.v2,v=b.dataset.value;vDraft();if(a==='close-dialog')return $('#source-dialog').close();if(a==='explain')return vDialog(b.childNodes[0]?.textContent||'详细说明',`<p>${esc(b.dataset.detail)}</p>`);if(a==='source')return vSourceDialog(b.dataset.kind,v);if(a==='photo')return vPhotoDialog(v);if(a==='station'){const s=D.stations.find(x=>x.name===v);return vDialog(v+' · 周边状态',`<p>坐标 ${s.lat}, ${s.lon}（WGS84，OSM来源）</p><p>运营、商场营业及拥挤状态：尚未取得实时信息。</p><a href="https://www.openstreetmap.org/node/${s.osm_id}" target="_blank" rel="noopener">公开节点 ↗</a><p><button data-v2="set-destination" data-value="${v}">设为目的地</button></p>`);}if(a==='weather')return vFetchWeather();if(a==='export')return vExportDialog();if(a==='export-record')return vExportDialog(vRecord(v));if(a==='share')return vShare();if(a==='share-record')return vShare(vRecord(v));if(a==='copy-share'){try{await navigator.clipboard.writeText(vShareUrl);toast('快照链接已复制')}catch{vDialog('复制链接',`<textarea readonly style="width:100%;height:100px">${esc(vShareUrl)}</textarea><small>请手动复制；接收者仍需本站访问权限。</small>`)}return;}if(a==='native-share'){if(navigator.share){try{await navigator.share({title:'深雨知路查询快照',url:vShareUrl})}catch{toast('分享未完成')}}else toast('当前浏览器不支持系统分享，请复制链接');return;}if(a==='share-image'){vExportDialog(vShareRecord);return;}if(a==='feedback-export'){download('深雨知路_待核验上报摘要.json',JSON.stringify({status:'本地线索，未提交官方',feedback:stored('sy-v2-feedback').map(({photo,...f})=>f)},null,2),'application/json');return;}if(a==='speak')return vSpeak();if(a==='restore')return vRestore(vRecord(v));if(a==='add-compare')return vRestore(vRecord(v),true);if(a==='query-preset'){V2.query=v;V2.answer=vAnswer(v);V2.page='query';}if(a==='page'){V2.page=v;window.scrollTo(0,0);}if(a==='mode'){V2.requestSeq++;V2.loading=false;V2.mode=v;V2.plans=[];V2.selected=[];V2.focus=null;V2.answer='';V2.shared=null;}if(a==='transport')V2.transport=v;if(a==='departure')V2.departure=v;if(a==='set-planned'){V2.departure='planned';V2.page='dashboard';}if(a==='try-mode'){V2.transport=v;V2.page='dashboard';toast('已切换出行方式，点击“添加出行方案”进行比较');}if(a==='add-via')V2.vias.push('');if(a==='remove-via')V2.vias.splice(Number(v),1);if(a==='focus'){const p=V2.plans.find(p=>p.id===v);if(p){V2.focus=v;V2.origin=p.origin;V2.destination=p.destination;V2.vias=p.vias||[];V2.transport=p.transport;V2.at=p.at;V2.departure=p.planned?'planned':'immediate';V2.planned=p.planned;V2.answer='';if(V2.weather?.place!==(vResolve(p.destination)||vResolve(p.origin))?.name)V2.weather=null;}}if(a==='delete-plan'){V2.plans=V2.plans.filter(p=>p.id!==v);V2.selected=V2.selected.filter(id=>id!==v);if(V2.focus===v)V2.focus=V2.selected[0]||null;}if(a==='delete-record')save('sy-v2-history',stored('sy-v2-history').filter(x=>x.id!==v));if(a==='delete-feedback')save('sy-v2-feedback',stored('sy-v2-feedback').filter(x=>x.id!==v));if(a==='map-tab')V2.mapTab=v;if(a==='event-tab')V2.eventTab=v;if(a==='replay'){V2.requestSeq++;V2.loading=false;V2.mode='history';V2.at=v;V2.page='dashboard';V2.plans=[];V2.selected=[];V2.focus=null;V2.answer='';}if(a==='set-destination'){V2.destination=v;V2.page='dashboard';$('#source-dialog').close();}vRender();});
document.addEventListener('change',e=>{const id=vFormId(e.target);if(e.target.dataset?.plan){const p=V2.plans.find(p=>p.id===e.target.dataset.plan);if(p){if(e.target.checked){if(!V2.selected.includes(p.id))V2.selected.push(p.id)}else V2.selected=V2.selected.filter(x=>x!==p.id);}vDraft();vRender();return;}if(id==='v2-at'){V2.requestSeq++;V2.loading=false;V2.at=e.target.value||'2023-09-08T10:00';V2.plans=[];V2.selected=[];V2.focus=null;V2.answer='';}if(id==='v2-planned')V2.planned=e.target.value;if(id==='v2-event-select'||id==='v2-recap-event')V2.eventId=e.target.value;if(id==='v2-range-start')V2.rangeStart=e.target.value;if(id==='v2-range-end')V2.rangeEnd=e.target.value;if(id==='v2-font')V2.settings.font=Number(e.target.value);if(id==='v2-voice')V2.settings.voice=e.target.checked;if(id==='v2-alert')V2.settings.alert=e.target.checked;if(id==='v2-lead')V2.settings.lead=Number(e.target.value);if(id.startsWith('v2-')){vDraft();save('sy-v2-settings',V2.settings);vRender();}});
document.addEventListener('submit',async e=>{const f=e.target;if(!vFormId(f).startsWith('v2-'))return;e.preventDefault();const values=Object.fromEntries(new FormData(f));if(vFormId(f)==='v2-journey')return vAddPlan();if(vFormId(f)==='v2-query'){V2.query=values.question.trim();V2.answer=vAnswer(V2.query);vRender();}if(vFormId(f)==='v2-feedback'){if(new Date(values.observed+':00+08:00')>businessNow())return toast('观察时间不能晚于现在');try{const photo=await vReadPhoto(values.photo);const x={...values,id:vId(),photo,submitted:businessNow().toISOString(),actual_submitted_at:new Date().toISOString(),test_record:typeof V9!=='undefined'&&V9.active,status:'待核验'};const rows=stored('sy-v2-feedback');rows.push(x);if(save('sy-v2-feedback',rows)){toast('反馈已保存；未向官方发送');vRender()}}catch(err){toast(err.message||'图片处理失败')}}if(vFormId(f)==='v2-export'){const s=vSnapshot(vExportRecord),parts=vExportParts(s,values);if(!parts.length&&!values.map&&!values.photos)return toast('至少选择一项内容');if(values.format==='txt'){download('深雨知路_查询信息.txt',parts.map(p=>p.title+'\n'+p.text).join('\n\n')+(values.map?'\n位置图不能包含在纯文本内，请选择HTML或PNG。':''));toast('按选择导出文本，图片未包含');}else if(values.format==='png'){try{await vPng(parts,s,values);toast('图片信息卡已导出')}catch{toast('图片导出失败，可改用HTML格式')}}else{const html=vExportHtml(parts,s,values);vDialog('信息卡预览',`<div class="exportpreview">${parts.map(p=>`<h3>${esc(p.title)}</h3><p style="white-space:pre-wrap">${esc(p.text)}</p>`).join('')}</div><button class="primary" id="v2-download-preview">下载HTML信息卡</button>`);$('#v2-download-preview').onclick=()=>download('深雨知路_信息卡.html',html,'text/html;charset=utf-8');}}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[data-v2]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
function vLoadShare(){if(!location.hash.startsWith('#snapshot='))return;try{if(location.hash.length>40000)throw Error();const payload=JSON.parse(decodeURIComponent(escape(atob(location.hash.slice(10)))));const s=payload.snapshot;if(payload.version!==2||!Array.isArray(s?.plans)||s.plans.length>10||!['now','history'].includes(s.mode))throw Error();const safe=s.plans.filter(p=>typeof p.origin==='string'&&typeof p.destination==='string'&&Array.isArray(p.vias)&&p.vias.length<=10&&(!p.geometry||p.geometry.type==='LineString'&&Array.isArray(p.geometry.coordinates)&&p.geometry.coordinates.length<=200&&p.geometry.coordinates.every(c=>Array.isArray(c)&&c.length===2&&c.every(Number.isFinite))));if(safe.length!==s.plans.length||typeof s.origin!=='string'||typeof s.destination!=='string')throw Error();for(const p of safe){if(p.vias.some(v=>typeof v!=='string')||p.origin.length>300||p.destination.length>300||!Array.isArray(p.coords||[])||(p.coords||[]).some(c=>!Number.isFinite(c.lat)||!Number.isFinite(c.lon))||p.geometry?.coordinates.some(c=>c[0]<113.5||c[0]>114.8||c[1]<22.2||c[1]>23.1))throw Error();p.id=String(p.id).slice(0,100);p.duration=Number.isFinite(p.duration)&&p.duration>=0?p.duration:null;p.distance=Number.isFinite(p.distance)&&p.distance>=0?p.distance:null;p.roadNames=Array.isArray(p.roadNames)?p.roadNames.filter(x=>typeof x==='string').slice(0,40):[];}V2.shared=s;V2.mode=s.mode;V2.at=s.at||'2023-09-08T10:00';V2.origin=String(s.origin||'');V2.destination=String(s.destination||'');V2.vias=Array.isArray(s.vias)?s.vias:[];V2.plans=safe;V2.selected=safe.map(p=>p.id);V2.focus=safe[0]?.id;V2.departure=s.planned?'planned':'immediate';V2.planned=s.planned||'';V2.weather=null;toast('已载入分享快照；当前状态需重新查询');}catch{toast('分享链接无效或数据过大，未载入');}}
vLoadShare();vRender();

function vTimeControls(){return `<div class="v4time"><div class="seg"><button data-v2="mode" data-value="now" class="${V2.mode==='now'?'active':''}">现在</button><button data-v2="mode" data-value="history" class="${V2.mode==='history'?'active':''}">历史</button></div>${V2.mode==='now'?`<div class="chips" style="margin-top:12px"><button data-v2="departure" data-value="immediate" class="${V2.departure==='immediate'?'active':''}">现在出发</button><button data-v2="departure" data-value="planned" class="${V2.departure==='planned'?'active':''}">计划出发</button></div>${V2.departure==='planned'?`<div class="field" style="margin-top:12px"><label for="v2-planned">预计出发时间</label><input id="v2-planned" type="datetime-local" value="${V2.planned}"></div>`:''}`:`<div class="field" style="margin-top:12px"><label>历史事件</label><select id="v2-event-select"><option value="sep2023" ${V2.eventId==='sep2023'?'selected':''}>2023年9月深圳暴雨</option><option value="saola2023" ${V2.eventId==='saola2023'?'selected':''}>苏拉（资料待补）</option></select></div><div class="field" style="margin-top:12px"><label>查看时刻</label><input id="v2-at" type="datetime-local" value="${V2.at}"></div><small>只读取此前已发布信息</small>`}</div>`}
function vPreferred(){return V2.plans.filter(p=>V2.selected.includes(p.id)&&Number.isFinite(p.duration)).sort((a,b)=>a.duration-b.duration)[0]?.id||null;}
function vRouteColor(p){return p.id===vPreferred()?'#159b8e':VC[V2.plans.indexOf(p)%VC.length];}
function v3FeedbackSafe(){const rows=typeof v3Feedback==='function'?v3Feedback():stored('sy-v2-feedback');return V2.mode==='history'?rows.filter(f=>new Date(f.submitted).getTime()<=new Date(V2.at+':00+08:00').getTime()):rows;}
